package server

// Authorization policies for the agents routes. See route_auth_policy_test.go
// for the classes; routePolicyFile says which file a new route belongs in.
func init() {
	declareRoutePolicies(map[string]routePolicy{
		"GET /api/v1/agents/{id}/avatar":                                public("agent avatar images are served to embeds without credentials"),
		"GET /api/v1/apps/{id}/avatar":                                  public("agent avatar images are served to embeds without credentials"),
		"GET /api/v1/agents":                                            object("listOrganizationApps", "redactAppsForUser"),
		"POST /api/v1/agents":                                           object("authorizeOrgMember"),
		"GET /api/v1/agents/{id}":                                       object("loadReadableAgent", "redactAppForUser"),
		"PUT /api/v1/agents/{id}":                                       object("authorizeUserToApp"),
		"DELETE /api/v1/agents/{id}":                                    object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/claude-subscription-status":            object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/daily-usage":                           object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/users-daily-usage":                     object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/llm-calls":                             object("authorizeOrgMember"),
		"GET /api/v1/agents/{id}/interactions":                          object("authorizeOrgMember"),
		"GET /api/v1/agents/{id}/step-info":                             object("authorizeOrgMember"),
		"POST /api/v1/agents/{id}/api-actions":                          noAuthzHelper("inline owner check: app.Owner == user.ID or app.Global"),
		"GET /api/v1/agents/{id}/user-access":                           noAuthzHelper("reports the caller's own permissions on the app (all false for someone else's)"),
		"GET /api/v1/agents/{id}/access-grants":                         object("authorizeUserToApp", "authorizeUserToAppAccessGrants"),
		"POST /api/v1/agents/{id}/access-grants":                        object("authorizeUserToAppAccessGrants"),
		"DELETE /api/v1/agents/{id}/access-grants/{grant_id}":           object("authorizeUserToAppAccessGrants"),
		"POST /api/v1/agents/{id}/duplicate":                            object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/memories":                              object("authorizeUserToApp"),
		"DELETE /api/v1/agents/{id}/memories/{memory_id}":               object("authorizeUserToApp"),
		"GET /api/v1/agents/{agent_id}/triggers":                        object("authorizeUserToApp"),
		"POST /api/v1/agents/{id}/avatar":                               object("authorizeUserToApp"),
		"DELETE /api/v1/agents/{id}/avatar":                             object("authorizeUserToApp"),
		"GET /api/v1/agents/{id}/trigger-status":                        object("authorizeUserToApp"),
		"POST /api/v1/agents/{id}/skills/{skill}/enable":                object("authorizeUserToApp"),
		"GET /api/v1/agents/{agent_id}/evaluation-suites":               object("getAppForEvaluation"),
		"POST /api/v1/agents/{agent_id}/evaluation-suites":              object("getAppForEvaluation"),
		"GET /api/v1/agents/{agent_id}/evaluation-suites/{id}":          object("canAccessEvaluationSuite"),
		"PUT /api/v1/agents/{agent_id}/evaluation-suites/{id}":          object("canAccessEvaluationSuite"),
		"DELETE /api/v1/agents/{agent_id}/evaluation-suites/{id}":       object("canAccessEvaluationSuite"),
		"POST /api/v1/agents/{agent_id}/evaluation-suites/{id}/runs":    object("canAccessEvaluationSuite", "getAppForEvaluation"),
		"GET /api/v1/agents/{agent_id}/evaluation-suites/{id}/runs":     object("getAppForEvaluation"),
		"GET /api/v1/agents/{agent_id}/evaluation-runs/{run_id}":        object("getAppForEvaluation"),
		"DELETE /api/v1/agents/{agent_id}/evaluation-runs/{run_id}":     object("getAppForEvaluation"),
		"GET /api/v1/agents/{agent_id}/evaluation-runs/{run_id}/stream": object("getAppForEvaluation"),
		"GET /api/v1/apps":                                              object("listOrganizationApps", "redactAppsForUser"),
		"POST /api/v1/apps":                                             object("authorizeOrgMember"),
		"GET /api/v1/apps/{id}":                                         object("loadReadableAgent", "redactAppForUser"),
		"PUT /api/v1/apps/{id}":                                         object("authorizeUserToApp"),
		"DELETE /api/v1/apps/{id}":                                      object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/claude-subscription-status":              object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/daily-usage":                             object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/users-daily-usage":                       object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/llm-calls":                               object("authorizeOrgMember"),
		"GET /api/v1/apps/{id}/interactions":                            object("authorizeOrgMember"),
		"GET /api/v1/apps/{id}/step-info":                               object("authorizeOrgMember"),
		"POST /api/v1/apps/{id}/api-actions":                            noAuthzHelper("inline owner check: app.Owner == user.ID or app.Global"),
		"GET /api/v1/apps/{id}/user-access":                             noAuthzHelper("reports the caller's own permissions on the app (all false for someone else's)"),
		"GET /api/v1/apps/{id}/access-grants":                           object("authorizeUserToApp", "authorizeUserToAppAccessGrants"),
		"POST /api/v1/apps/{id}/access-grants":                          object("authorizeUserToAppAccessGrants"),
		"DELETE /api/v1/apps/{id}/access-grants/{grant_id}":             object("authorizeUserToAppAccessGrants"),
		"POST /api/v1/apps/{id}/duplicate":                              object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/memories":                                object("authorizeUserToApp"),
		"DELETE /api/v1/apps/{id}/memories/{memory_id}":                 object("authorizeUserToApp"),
		"GET /api/v1/apps/{agent_id}/triggers":                          object("authorizeUserToApp"),
		"POST /api/v1/apps/{id}/avatar":                                 object("authorizeUserToApp"),
		"DELETE /api/v1/apps/{id}/avatar":                               object("authorizeUserToApp"),
		"GET /api/v1/apps/{id}/trigger-status":                          object("authorizeUserToApp"),
		"POST /api/v1/apps/{id}/skills/{skill}/enable":                  object("authorizeUserToApp"),
		"GET /api/v1/apps/{agent_id}/evaluation-suites":                 object("getAppForEvaluation"),
		"POST /api/v1/apps/{agent_id}/evaluation-suites":                object("getAppForEvaluation"),
		"GET /api/v1/apps/{agent_id}/evaluation-suites/{id}":            object("canAccessEvaluationSuite"),
		"PUT /api/v1/apps/{agent_id}/evaluation-suites/{id}":            object("canAccessEvaluationSuite"),
		"DELETE /api/v1/apps/{agent_id}/evaluation-suites/{id}":         object("canAccessEvaluationSuite"),
		"POST /api/v1/apps/{agent_id}/evaluation-suites/{id}/runs":      object("canAccessEvaluationSuite", "getAppForEvaluation"),
		"GET /api/v1/apps/{agent_id}/evaluation-suites/{id}/runs":       object("getAppForEvaluation"),
		"GET /api/v1/apps/{agent_id}/evaluation-runs/{run_id}":          object("getAppForEvaluation"),
		"DELETE /api/v1/apps/{agent_id}/evaluation-runs/{run_id}":       object("getAppForEvaluation"),
		"GET /api/v1/apps/{agent_id}/evaluation-runs/{run_id}/stream":   object("getAppForEvaluation"),
		"GET /api/v1/triggers":                                          user(),
		"POST /api/v1/triggers":                                         object("authorizeUserToApp"),
		"PUT /api/v1/triggers/{trigger_id}":                             object("authorizeUserToApp", "authorizeUserToTrigger"),
		"DELETE /api/v1/triggers/{trigger_id}":                          object("authorizeUserToTrigger"),
		"POST /api/v1/triggers/{trigger_id}/execute":                    object("authorizeUserToApp"),
		"GET /api/v1/triggers/{trigger_id}/executions":                  object("authorizeUserToTrigger"),
		"GET /api/v1/knowledge":                                         object("authorizeOrgMember", "authorizeUserToApp"),
		"GET /api/v1/knowledge/{id}":                                    noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"DELETE /api/v1/knowledge/{id}":                                 noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"POST /api/v1/knowledge/{id}/refresh":                           noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"POST /api/v1/knowledge/{id}/complete":                          noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"GET /api/v1/knowledge/{id}/versions":                           noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"GET /api/v1/knowledge/{id}/download":                           noAuthzHelper("ownsKnowledge: the owner, and a project-scoped key only for its project's agents"),
		"GET /api/v1/skills":                                            user(),
		"GET /api/v1/skills/{id}":                                       noAuthzHelper("built-in YAML skill definitions, the same for every user"),
		"POST /api/v1/skills/reload":                                    user(),
		"POST /api/v1/skills/validate":                                  user(),
		"GET /api/v1/context-menu":                                      object("authorizeUserToApp"),
		"GET /api/v1/agent-tools":                                       user(),
	})
}
